window.WorkshopEntry={mount(container,{onComplete}={}){
 const p=GamePalette.tokens,screen=document.createElement('section');screen.className='entry-transition';screen.hidden=true;screen.setAttribute('aria-label','공방 입장 연출');screen.innerHTML='<span class="entry-eyebrow">이딴게 무기?</span><span class="entry-number">THE LITTLE WORKSHOP</span><canvas class="entry-building" width="256" height="144" aria-hidden="true"></canvas><div class="entry-caption"><h2 role="status">공방 문을 여는 중</h2><p>새 종이와 잉크를 준비할게.</p><div class="entry-ticks" aria-hidden="true"><i></i><i></i><i></i></div></div>';container.append(screen);
 const arrival=document.createElement('section');arrival.className='entry-arrival';arrival.hidden=true;arrival.innerHTML='<canvas class="entry-room" aria-label="불이 켜진 도트 공방"></canvas><div class="entry-arrival-copy"><small>모험가의 공방</small><h2>자, 뭘 그려볼까?</h2><p>공방에 도착했어.<br>이제 네 상상을 꺼낼 차례야.</p><button type="button">전환 다시 보기</button><a href="craft.html">실제 공방 보기</a></div>';container.append(arrival);GameScenery.paint(arrival.querySelector('canvas'),'workshop');
 const canvas=screen.querySelector('canvas'),c=canvas.getContext('2d'),dots=[...screen.querySelectorAll('.entry-ticks i')],title=screen.querySelector('h2');let raf=0,timer=null,busy=false,revision=0;
 const r=(color,x,y,w,h)=>{c.fillStyle=p[color];c.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));};
 function paint(t){const lit=t>.12,open=Math.min(1,Math.max(0,(t-.25)/.42));c.imageSmoothingEnabled=false;r('dark',0,0,256,144);for(let i=0;i<24;i++)r(i%5?'muted':'metal',(i*47+11)%256,(i*29+9)%86,1,1);
  r('ink',43,103,170,4);r('ink',50,54,156,51);r('muted',55,59,146,44);r('dark',58,62,140,40);for(let y=65;y<100;y+=11){r('muted',57,y,143,1);for(let x=61+(y%2)*12;x<199;x+=26)r('muted',x,y-7,1,7);}for(let i=0;i<7;i++){r('ink',48+i*11,51-i*4,160-i*22,5);r(i%2?'ground':'rock',52+i*11,51-i*4,152-i*22,2);}r('ink',161,18,10,19);r('muted',163,20,6,14);r('ink',158,16,16,4);
  r('ink',103,43,52,13);r('rock',105,45,48,9);r('electric',110,48,10,2);r('paper',124,48,21,2);r('paper',114,51,27,1);for(const x of [67,167]){r('ink',x-2,66,25,24);r(lit?'electric':'muted',x,68,21,20);r(lit?'paper':'dark',x+2,70,6,7);r('ink',x+10,68,2,20);r('ink',x,78,21,2);r('ink',x-4,91,29,3);}
  r('ink',111,61,35,44);r(open>0?'electric':'dark',114,64,29,38);if(open>0){const extent=Math.round(open*28);for(let y=105;y<125;y++)r(y%3?'rock':'electric',115-extent*(y-104)/25,y,26+extent*2*(y-104)/25,1);r('paper',117,67,22,32);r('electric',115,69,2,31);}const width=Math.max(2,Math.round(28*(1-open)));r('ink',114,64,width,39);if(width>4){r('ground',116,66,width-3,35);r('rock',117,67,Math.max(1,width-5),1);r('ink',117,80,Math.max(1,width-5),1);r('electric',114+Math.max(2,width-5),84,2,2);}r('ink',107,104,43,3);r('muted',103,108,51,3);r('ink',98,112,61,3);r('normal',105,108,47,1);
  r('ink',63,98,14,8);r('ground',65,99,10,6);r('nature',69,90,2,10);r('bug',65,91,5,3);r('nature',71,88,5,3);r('ink',182,97,13,8);r('metal',184,99,9,5);r('ink',187,91,2,7);r('electric',189,91,3,3);if(lit){r('ink',102,55,4,7);r('electric',103,58,2,3);r('ink',148,55,4,7);r('electric',149,58,2,3);}if(t>.52)for(let i=0;i<5;i++)r('paper',119+(i*7)%19,90-((t*45+i*13)%30),1,1);
 }
 function play(){if(busy)return;window.GameAudio?.scene('loading');busy=true;revision++;const token=revision;arrival.hidden=true;screen.hidden=false;screen.classList.remove('finished','entering');title.textContent='공방 문을 여는 중';dots.forEach(d=>d.classList.remove('on'));let start;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,duration=2720;const frame=now=>{if(token!==revision)return;start??=now;const t=Math.min(1,(now-start)/duration);paint(t);dots.forEach((dot,i)=>dot.classList.toggle('on',t>(i+1)*.24));screen.classList.toggle('entering',t>.65);if(t>.55)title.textContent='네 낙서를 기다리는 중';if(t<1){raf=requestAnimationFrame(frame);return;}screen.classList.add('finished');timer=setTimeout(()=>{if(token!==revision)return;if(onComplete){onComplete();return;}screen.hidden=true;arrival.hidden=false;busy=false;arrival.querySelector('button').focus({preventScroll:true});},280);};raf=requestAnimationFrame(frame);}
 arrival.querySelector('button').addEventListener('click',play);window.addEventListener('pagehide',()=>{revision++;cancelAnimationFrame(raf);clearTimeout(timer);});return{play};
}};
